import { HowlOptions } from 'howler';
import { ALPHA_MODES, SCALE_MODE, TEXTURE_FORMATS, WRAP_MODE } from 'pixi.js';
import { Config } from 'webfontloader';

export interface ICoreAssetConfig {
    name: string;
    isLazyLoad?: boolean;
}

export interface IBaseAssetConfig extends ICoreAssetConfig {
    url: string;
    dependencies?: IBaseAssetConfig[];
}

export type ISoundSpriteConfig = Record<string, { start: number, end: number }>;
export interface IAnimationAssetConfig extends IBaseAssetConfig {
    // Pixi-8 TODO: investigate this, isn't used in arcade products so ignoring for now
    options?: any; // Don't think it's needed now but want to check against bingo products using it
    textureSettings?: ITextureSettings;
    dependencies?: ISpriteSheetAssetConfig[];
}

export interface ISpriteSheetAssetConfig extends IBaseAssetConfig {
    textureSettings?: ITextureSettings;
    dependencies?: ITextureAssetConfig[];
}

export interface ITextureAssetConfig extends IBaseAssetConfig {
    textureSettings?: ITextureSettings;
}

/** @deprecated Use `IHowlSoundAssetConfig` type instead */
export interface ILegacySoundAssetConfig extends Omit<HowlOptions, 'src'>, ICoreAssetConfig {
    /** @deprecated this will be converted to IHowlSoundAssetConfig "sprite" property */
    sprites?: ISoundSpriteConfig;
    /** @deprecated this will be converted to IHowlSoundAssetConfig "src" property */
    url: string;
}
export type IHowlSoundAssetConfig = HowlOptions & ICoreAssetConfig;

export type ISoundAssetConfig = ILegacySoundAssetConfig | IHowlSoundAssetConfig;

export interface ISDFAssetConfig extends IBaseAssetConfig {
    textureSettings?: ITextureSettings;
}

export type HowlerSprites = Record<string, [number, number]>;

export interface IAssetList {
    animations?: IAnimationAssetConfig[];
    spriteSheets?: ISpriteSheetAssetConfig[];
    textures?: ITextureAssetConfig[];
    sounds?: ISoundAssetConfig[];
    data?: IBaseAssetConfig[];
    bitmapFonts?: IBaseAssetConfig[];
    webFonts?: Config;
    sdfFonts?: ISDFAssetConfig[];
}

export type LazyAssetKeys = { [K in keyof Omit<IAssetList, 'webFonts'>]: string[] }

export interface ITextureSettings {
    autoGenerateMipmaps?: boolean;
    maxAnisotropy?: number;
    wrapMode?: WRAP_MODE;
    scaleMode?: SCALE_MODE;
    format?: TEXTURE_FORMATS;
    alphaMode?: ALPHA_MODES;
}

export interface IAssetConfig {
    baseUrl: string;
    assetList: IAssetList;
    skin: string;
    version: string;
}

type Locale = 'en-gb' | 'it-it' | 'es-es' | 'dk-dk' | 'se-se';
export type AssetRegion = Locale | 'international';

type OverrideAssetConfig = Omit<IBaseAssetConfig, 'isLazyLoad'>;
type OverrideAssetList = { [Property in keyof Omit<IAssetList, 'webFonts'>]?: OverrideAssetConfig[] };

type DefaultAssetData = {
    'default': IAssetList;
};

type RegionAssetData = Partial<Record<AssetRegion, OverrideAssetList>>;

/** Asset list with a required `default` locale and optional per-region overrides. */
export type AssetData = DefaultAssetData & RegionAssetData;

export type AssetConfigs = { assetConfig: IAssetConfig, lazyAssetConfig: IAssetConfig | undefined; };

export interface IBaseBingoAssetConfig {
    isLazyLoad?: boolean
}

export interface IBingoSpriteSheetAssetConfig extends IBaseBingoAssetConfig {
    location: string;
    textureSettings?: ITextureSettings;
    multipackIndex?: number;
}

export interface IBingoTextureAssetConfig extends IBaseBingoAssetConfig {
    name: string;
    ext: string;
    textureSettings?: ITextureSettings;
}

export interface IBingoSVGAssetConfig {
    base64: string;
    textureSettings?: ITextureSettings;
}

export interface IBingoSpineAssetConfig extends IBaseBingoAssetConfig {
    location: string;
    atlasName: string;
    configName?: string;
    fileExtension?: '.json' | '.skel';
    textureSettings?: ITextureSettings;
    metadata?: {
        imageNamePrefix: string;
    }
}

export interface IBingoSDFFontAssetConfig extends IBaseBingoAssetConfig {
    texture: string,
    fnt: string,
    textureSettings?: ITextureSettings
}

export interface IBingoAssetConfig {
    fonts: Record<string, { families: Array<string> }>;
    spritesheets: Record<string, IBingoSpriteSheetAssetConfig>;
    remotespritesheets: Record<string, IBingoSpriteSheetAssetConfig>;
    textures: Record<string, IBingoTextureAssetConfig>;
    spine: Record<string, IBingoSpineAssetConfig>;
    sound: Array<ISoundAssetConfig>;
    sdf?: Record<string, IBingoSDFFontAssetConfig>;
    svg?: Record<string, IBingoSVGAssetConfig>;
}